CREATE OR REPLACE PROCEDURE generate_brand_translations_materialized_view()
LANGUAGE PLPGSQL AS $$
BEGIN
    -- Drop existing materialized views if they exist
    BEGIN
        EXECUTE 'DROP MATERIALIZED VIEW IF EXISTS "brand_translations_en-US"';
        RAISE NOTICE 'Dropped materialized view "brand_translations_en-US" if it existed.';
    EXCEPTION
        WHEN OTHERS THEN
            RAISE NOTICE 'Failed to drop materialized view "brand_translations_en-US". Error: %', SQLERRM;
    END;

    BEGIN
        EXECUTE 'DROP MATERIALIZED VIEW IF EXISTS "brand_translations_ja-Kana"';
        RAISE NOTICE 'Dropped materialized view "brand_translations_ja-Kana" if it existed.';
    EXCEPTION
        WHEN OTHERS THEN
            RAISE NOTICE 'Failed to drop materialized view "brand_translations_ja-Kana". Error: %', SQLERRM;
    END;

    BEGIN
        EXECUTE 'DROP MATERIALIZED VIEW IF EXISTS "brand_translations_ja-JP"';
        RAISE NOTICE 'Dropped materialized view "brand_translations_ja-JP" if it existed.';
    EXCEPTION
        WHEN OTHERS THEN
            RAISE NOTICE 'Failed to drop materialized view "brand_translations_ja-JP". Error: %', SQLERRM;
    END;

    -- Create a permanent table to hold the data
    CREATE TABLE IF NOT EXISTS brand_translations_data (
        alphabets TEXT,
        "ja-JP" TEXT,
        "ja-Kana" TEXT,
        "en-US" TEXT
    );

    -- Clear existing data from the table
    TRUNCATE TABLE brand_translations_data;

