    -- Create the "brand_translations_en-US" materialized view
    EXECUTE '
    CREATE MATERIALIZED VIEW "brand_translations_en-US" AS
    SELECT 
        b.id, 
        COALESCE(
            la.alphabet, 
            ''Others''
        ) AS alphabet, 
        b.name 
    FROM 
        brands b 
    LEFT JOIN 
        languages lt ON lt.code = ''en-US'' 
    LEFT JOIN 
        language_alphabets la ON lower(substring(b.name, 1, 1)) = lower(la.alphabet) 
            AND la."languageId" = lt.id 
    UNION ALL 
    SELECT 
        NULL AS id,
        la.alphabet AS alphabet,
        NULL AS name
    FROM 
        language_alphabets la 
    LEFT JOIN 
        languages lt ON lt.code = ''en-US'' 
    WHERE 
        lt.id = la."languageId" 
        AND NOT EXISTS (
            SELECT 
                1
            FROM 
                brands b
            WHERE
                lower(substring(b.name, 1, 1)) = lower(la.alphabet) 
                AND lt.id = la."languageId"
        )';

    -- Create the "brand_translations_ja-Kana" materialized view
    EXECUTE '
    CREATE MATERIALIZED VIEW "brand_translations_ja-Kana" AS
    SELECT DISTINCT
        b.id,
        COALESCE(
            btd.alphabets, 
            COALESCE(la.alphabet, ''その他'')
        ) AS alphabet,
        bt.name AS name
    FROM 
        brands b
    LEFT JOIN 
        brand_translations bt ON b.id = bt."brandId"
        AND bt."languageId" = (
            SELECT 
                id 
            FROM 
                languages 
            WHERE 
                code = ''ja-Kana''
        ) 
    LEFT JOIN 
        brand_translations_data btd ON btd."ja-Kana" = bt.name
    LEFT JOIN 
        languages lt ON lt.code = ''ja-Kana'' 
    LEFT JOIN 
        language_alphabets la ON lower(substring(bt.name, 1, 1)) = lower(la.alphabet) 
            AND la."languageId" = lt.id 
    WHERE 
        lt.code = ''ja-Kana''';
    RAISE NOTICE 'Created materialized view "brand_translations_ja-Kana".';

    -- Create the "brand_translations_ja-JP" materialized view
    EXECUTE '
    CREATE MATERIALIZED VIEW "brand_translations_ja-JP" AS
    SELECT DISTINCT
        b.id,
        COALESCE(
            btd.alphabets,
            COALESCE(la.alphabet, ''その他'')
        ) AS alphabet,
        bt.name AS name
    FROM 
        brands b
    LEFT JOIN 
        brand_translations bt ON b.id = bt."brandId"
        AND bt."languageId" = (
            SELECT 
                id 
            FROM 
                languages 
            WHERE 
                code = ''ja-JP''
        ) 
    LEFT JOIN 
        brand_translations_data btd ON btd."ja-JP" = bt.name
    LEFT JOIN 
        languages lt ON lt.code = ''ja-JP'' 
    LEFT JOIN 
        language_alphabets la ON lower(substring(bt.name, 1, 1)) = lower(la.alphabet) 
            AND la."languageId" = lt.id 
    WHERE 
        lt.code = ''ja-JP''';
    RAISE NOTICE 'Created materialized view "brand_translations_ja-JP".';

    -- Clean up the permanent table if not needed
    -- DROP TABLE IF EXISTS brand_translations_data;
END;
$$;

-- Call the procedure to generate the materialized views
CALL generate_brand_translations_materialized_view();
